// Applied rules: [III②, C3, C6]
// Skipped rules: [C12: Subsumed by III② on hit [0]: the oversized eager zero-init is the heap dictionary buffer, and replacing manual malloc/free with an owned Rust buffer removes the original eager-zero-init/memset shape from consideration more cleanly than a separate MaybeUninit prefix rewrite.; III③: Hit [8] is a memset in the decompression setup/boundary path, but once III② rewrites the allocation to an owned Rust buffer, the zero-initialization idiom should be expressed through the container construction instead of a separate libc-mem rewrite. Applying III③ independently would be redundant and risks fighting the container choice.; III①: Although hit [5] is a callback parameter indirect call, this is a public unsafe function and the generic monomorphization route would require cross-function signature/caller rewrites. For this plan, C3+C6 provide an intra-function devirtualization/hoisting path with lower risk; III① is therefore intentionally not applied.]
#[inline]
pub unsafe fn tinfl_decompress_mem_to_callback(
    mut pIn_buf: *const c_void,
    mut pIn_buf_size: *mut size_t,
    mut pPut_buf_func: tinfl_put_buf_func_ptr,
    mut pPut_buf_user: *mut c_void,
    mut flags: c_int,
) -> c_int {
    let mut result: c_int = 0 as c_int;
    let mut decomp: tinfl_decompressor = tinfl_decompressor_tag {
        m_state: 0,
        m_num_bits: 0,
        m_zhdr0: 0,
        m_zhdr1: 0,
        m_z_adler32: 0,
        m_final: 0,
        m_type: 0,
        m_check_adler32: 0,
        m_dist: 0,
        m_counter: 0,
        m_num_extra: 0,
        m_table_sizes: [0; 3],
        m_bit_buf: 0,
        m_dist_from_out_buf_start: 0,
        m_look_up: [[0; 1024]; 3],
        m_tree_0: [0; 576],
        m_tree_1: [0; 64],
        m_tree_2: [0; 38],
        m_code_size_0: [0; 288],
        m_code_size_1: [0; 32],
        m_code_size_2: [0; 19],
        m_raw_header: [0; 4],
        m_len_codes: [0; 457],
    };
    let mut dict = vec![0 as mz_uint8; 32768usize];
    let pDict: *mut mz_uint8 = dict.as_mut_ptr();
    let mut in_buf_ofs: size_t = 0 as size_t;
    let mut dict_ofs: size_t = 0 as size_t;
    let total_in_size: size_t = *pIn_buf_size;
    let put_buf_func = pPut_buf_func.expect("non-null function pointer");
    let put_buf_user = pPut_buf_user;
    let decomp_flags: mz_uint32 = (flags
        & !(TINFL_FLAG_HAS_MORE_INPUT as c_int
            | TINFL_FLAG_USING_NON_WRAPPING_OUTPUT_BUF as c_int)) as mz_uint32;
    decomp.m_state = 0 as mz_uint32;
    loop {
        let mut in_buf_size: size_t = total_in_size.wrapping_sub(in_buf_ofs);
        let mut dst_buf_size: size_t = (TINFL_LZ_DICT_SIZE as size_t).wrapping_sub(dict_ofs);
        let status: tinfl_status = tinfl_decompress(
            &raw mut decomp,
            (pIn_buf as *const mz_uint8).offset(in_buf_ofs as isize),
            &raw mut in_buf_size,
            pDict,
            pDict.offset(dict_ofs as isize),
            &raw mut dst_buf_size,
            decomp_flags,
        );
        in_buf_ofs = in_buf_ofs.wrapping_add(in_buf_size);
        if dst_buf_size != 0
            && put_buf_func(
                pDict.offset(dict_ofs as isize) as *const c_void,
                dst_buf_size as c_int,
                put_buf_user,
            ) == 0
        {
            break;
        }
        if status as c_int != TINFL_STATUS_HAS_MORE_OUTPUT as c_int {
            result = (status as c_int == TINFL_STATUS_DONE as c_int) as c_int;
            break;
        } else {
            dict_ofs = dict_ofs.wrapping_add(dst_buf_size)
                & (TINFL_LZ_DICT_SIZE - 1 as c_int) as size_t;
        }
    }
    *pIn_buf_size = in_buf_ofs;
    return result;
}

